const p = $json;
const required = ['event_id','organization_name','challenge_statement','beneficiary_count','urgency','requested_outcome','data_sensitivity','submitted_at'];
const missing = required.filter(k => p[k] === undefined || p[k] === null || (typeof p[k] === 'string' && !p[k].trim()));
const errors = [];
const urgencyPoints = {low:10, medium:20, high:30, critical:40};
const sensitivityPoints = {none:0, personal:10, special_category:20};
if (!(p.urgency in urgencyPoints)) errors.push('urgency must be one of: low, medium, high, critical');
if (!(p.data_sensitivity in sensitivityPoints)) errors.push('data_sensitivity must be one of: none, personal, special_category');
if (!Number.isInteger(p.beneficiary_count) || p.beneficiary_count < 1) errors.push('beneficiary_count must be a positive integer');
const normalisedEventId = String(p.event_id || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'missing_event_id';
const base = {intake_id:`intake_${normalisedEventId}`,source_event_id:p.event_id,organization_name:p.organization_name,processed_at:p.submitted_at,rules_version:'1.0.0',review_required:true};
if (missing.length || errors.length) return [{json:{...base,status:'needs_information',http_status:422,route:'intake_follow_up',priority_score:null,priority_band:null,readiness_score:0,missing_fields:missing,validation_errors:errors,risk_flags:['incomplete_or_invalid_intake'],summary:'The intake was not scored because required or valid data is missing.'}}];
const beneficiaryPoints = p.beneficiary_count >= 5000 ? 25 : p.beneficiary_count >= 1000 ? 20 : p.beneficiary_count >= 250 ? 12 : 5;
const score = Math.min(100, urgencyPoints[p.urgency] + beneficiaryPoints + sensitivityPoints[p.data_sensitivity] + (p.requested_outcome.trim().length >= 15 ? 10 : 3) + (p.challenge_statement.trim().length >= 80 ? 5 : 2));
const readiness = [p.challenge_statement.trim().length >= 80,p.requested_outcome.trim().length >= 15,p.beneficiary_count > 0,p.urgency in urgencyPoints,p.data_sensitivity in sensitivityPoints].filter(Boolean).length * 20;
const band = score >= 80 ? 'critical' : score >= 60 ? 'high' : 'standard';
const route = p.data_sensitivity === 'special_category' || score >= 75 ? 'senior_impact_consultant' : 'impact_consultant';
const flags = [];
if (p.data_sensitivity !== 'none') flags.push(`${p.data_sensitivity}_data_requires_authorised_handling`);
if (p.beneficiary_count >= 1000) flags.push('high_beneficiary_reach');
if (['high','critical'].includes(p.urgency)) flags.push('time_sensitive_case');
return [{json:{...base,status:'ready_for_consultant_review',http_status:200,route,priority_score:score,priority_band:band,readiness_score:readiness,missing_fields:[],validation_errors:[],risk_flags:flags,summary:`${p.organization_name} submitted a ${p.urgency}-urgency challenge affecting approximately ${p.beneficiary_count} beneficiaries. A consultant must verify the diagnosis before client use.`}}];
